mapper.sql:
WHERE u.valid = 1

    AND u.user_id = #{user.userId}


    AND u.mobile LIKE CONCAT('%', #{user.mobile}, '%')


    AND u.email LIKE CONCAT('%', #{user.email}, '%')


    AND u.username LIKE CONCAT('%', #{user.username}, '%')


    AND u.name LIKE CONCAT('%', #{user.name}, '%')


    AND ui.avatar_url LIKE CONCAT('%', #{userInfo.avatarUrl}, '%')


    AND ui.job_number LIKE CONCAT('%', #{userInfo.jobNumber}, '%')


    AND u.status = #{user.status}


    AND u.ctime  >=  #{user.ctime}


    AND u.ctime  <=  #{createdEndTime}
